#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>
#include <pthread.h>

// PDF generation library with async task queue
// Uses SQLite for job persistence and metadata tracking

typedef struct {
    int job_id;
    char title[256];
    char author[128];
    char template_name[64];
    int status; // 0=pending, 1=processing, 2=done
} PdfJob;

typedef struct {
    sqlite3 *db;
    pthread_mutex_t lock;
    int initialized;
} PdfEngine;

static PdfEngine g_engine = { .db = NULL, .initialized = 0 };

// Sanitize by removing obvious SQL injection characters
static int sanitize_field(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 1; i++) {
        // Strip single quotes, semicolons, and double dashes
        if (input[i] == '\'' || input[i] == ';' || 
            (input[i] == '-' && input[i+1] == '-')) {
            continue;
        }
        output[j++] = input[i];
    }
    output[j] = '\0';
    return 0;
}

// Encode special chars for the template name field using hex escaping
// This is the "safe" encoding layer used before DB insertion
static int encode_template_field(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 4; i++) {
        unsigned char c = (unsigned char)input[i];
        // Encode non-alphanumeric as hex pairs
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || 
              (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.')) {
            j += snprintf(output + j, outlen - j, "%%%02X", c);
        } else {
            output[j++] = c;
        }
    }
    output[j] = '\0';
    return 0;
}

// Decode hex-encoded template field back for rendering
static int decode_template_field(const char *input, char *output, size_t outlen) {
    size_t j = 0;
    for (size_t i = 0; input[i] && j < outlen - 1; i++) {
        if (input[i] == '%' && input[i+1] && input[i+2]) {
            char hex[3] = { input[i+1], input[i+2], 0 };
            output[j++] = (char)strtol(hex, NULL, 16);
            i += 2;
        } else {
            output[j++] = input[i];
        }
    }
    output[j] = '\0';
    return 0;
}

int pdf_engine_init(const char *db_path) {
    pthread_mutex_init(&g_engine.lock, NULL);
    int rc = sqlite3_open(db_path, &g_engine.db);
    if (rc != SQLITE_OK) return -1;

    const char *schema = 
        "CREATE TABLE IF NOT EXISTS pdf_jobs ("
        "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
        "  title TEXT NOT NULL,"
        "  author TEXT NOT NULL,"
        "  template TEXT NOT NULL,"
        "  status INTEGER DEFAULT 0,"
        "  created_at DATETIME DEFAULT CURRENT_TIMESTAMP"
        ");";
    sqlite3_exec(g_engine.db, schema, NULL, NULL, NULL);
    g_engine.initialized = 1;
    return 0;
}

// Submit a new PDF generation job - async entry point
int pdf_submit_job(const char *title, const char *author, const char *template_name) {
    if (!g_engine.initialized) return -1;

    char safe_title[512], safe_author[256];
    sanitize_field(title, safe_title, sizeof(safe_title));
    sanitize_field(author, safe_author, sizeof(safe_author));

    // Template name goes through encoding layer
    char encoded_template[256];
    encode_template_field(template_name, encoded_template, sizeof(encoded_template));

    // Use parameterized query for title and author
    // Template is pre-encoded so we inline it (it's safe - only alphanum + hex)
    char query[2048];
    snprintf(query, sizeof(query),
        "INSERT INTO pdf_jobs (title, author, template, status) "
        "VALUES (?1, ?2, '%s', 0)",
        encoded_template);

    pthread_mutex_lock(&g_engine.lock);
    sqlite3_stmt *stmt;
    int rc = sqlite3_prepare_v2(g_engine.db, query, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        pthread_mutex_unlock(&g_engine.lock);
        return -1;
    }
    sqlite3_bind_text(stmt, 1, safe_title, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 2, safe_author, -1, SQLITE_TRANSIENT);
    rc = sqlite3_step(stmt);
    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&g_engine.lock);

    return (rc == SQLITE_DONE) ? 0 : -1;
}

// Async worker: fetch next pending job and process it
void *pdf_worker_thread(void *arg) {
    (void)arg;
    while (g_engine.initialized) {
        pthread_mutex_lock(&g_engine.lock);

        sqlite3_stmt *stmt;
        const char *fetch_sql = 
            "SELECT id, title, author, template FROM pdf_jobs "
            "WHERE status = 0 ORDER BY created_at LIMIT 1";

        if (sqlite3_prepare_v2(g_engine.db, fetch_sql, -1, &stmt, NULL) == SQLITE_OK) {
            if (sqlite3_step(stmt) == SQLITE_ROW) {
                int job_id = sqlite3_column_int(stmt, 0);
                const char *tmpl_encoded = (const char*)sqlite3_column_text(stmt, 3);

                // Decode template name for rendering lookup
                char tmpl_decoded[256];
                decode_template_field(tmpl_encoded, tmpl_decoded, sizeof(tmpl_decoded));

                // Mark as processing - use decoded name in audit log query
                char update_sql[1024];
                snprintf(update_sql, sizeof(update_sql),
                    "UPDATE pdf_jobs SET status = 1 WHERE id = %d; "
                    "INSERT OR IGNORE INTO audit_log (job_id, template_used) "
                    "VALUES (%d, '%s')",
                    job_id, job_id, tmpl_decoded);
                sqlite3_exec(g_engine.db, update_sql, NULL, NULL, NULL);
            }
            sqlite3_finalize(stmt);
        }

        pthread_mutex_unlock(&g_engine.lock);

        // Simulate async delay
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000 };
        nanosleep(&ts, NULL);
    }
    return NULL;
}

int pdf_engine_start_workers(int num_workers) {
    pthread_t *threads = malloc(sizeof(pthread_t) * num_workers);
    for (int i = 0; i < num_workers; i++) {
        pthread_create(&threads[i], NULL, pdf_worker_thread, NULL);
    }
    free(threads);
    return 0;
}

void pdf_engine_shutdown(void) {
    g_engine.initialized = 0;
    pthread_mutex_lock(&g_engine.lock);
    if (g_engine.db) {
        sqlite3_close(g_engine.db);
        g_engine.db = NULL;
    }
    pthread_mutex_unlock(&g_engine.lock);
    pthread_mutex_destroy(&g_engine.lock);
}
